// Tool result bodies and file links (2026-10-18, user ruling "照官方原样"): the 3.6556.2 tool result body (c96d752d0 ROe
// → LOe → cb6930dae Cd: the command output, the pierre diff of an edit, the Shiki-highlighted Read preview, the search
// listings, …; 2.42304.0 KIe → GIe → Tu) and the file link (c856385e2 rr, 2.42304.0 In) are generated by
// scripts/extract-transcript-rows.mjs (w6-transcript-rows-cont); the host provides
// the session's file contexts (src/source-transcript-tool-rows.jsx). SSR in middleware mode only (hmr / ws off).
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';

const app = path.resolve(import.meta.dirname, '..');
const dir = path.join(app, 'src/generated/transcript-rows');
const reference = path.resolve(app, '../reference/snapshots/claude-3.6556.2-20261025-192807/ion-dist/assets/v1');
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
let server, Rows, Session, Adapters, Host, Tools;
before(async () => {
  server = await createServer({ configFile: false, root: app, plugins: [react()], server: { middlewareMode: true, hmr: false, ws: false, watch: null },
    appType: 'custom', logLevel: 'error' });
  Rows = await server.ssrLoadModule('/src/source-transcript-rows.jsx');
  Session = await server.ssrLoadModule('/src/source-session.jsx');
  Adapters = await server.ssrLoadModule('/src/source-transcript-rows-adapters.jsx');
  Host = await server.ssrLoadModule('/src/transcript-host-scope.mjs');
  Tools = await server.ssrLoadModule('/src/transcript-tool-scope.mjs');
});
after(() => server?.close());
const h = React.createElement;
const strip = html => html.replace(/ class="[^"]*"/g, '');
const render = (item, props = {}) => renderToStaticMarkup(h(Rows.TranscriptRowsScope, { sessionKey: 'code:s' },
  h(Session.SourceMessage, { item, sessionKey: 's', cwd: '/w', transcriptView: 'verbose', onOpenFileRef: () => {}, onOpenChanges: () => true, ...props })));

test('the result body and the file link are originals, sliced once', () => {
  const mark = manifest.modules.find(m => m.target === 'turn-mark.mjs');
  // 2.42304.0 Tu / Cu / ga / vl / bu / Fu / Au (data/transcript-module-map.json).
  for (const name of ['Cd', 'xd', 'Na', 'ru', '_d', 'Fd', 'kd']) assert.ok(mark.bindings.some(b => b.name === name), `cb6930dae ${name}`);
  const link = manifest.modules.find(m => m.source === 'c856385e2-aEyDzrcK.js');
  assert.equal(link.target, 'rows-c856385e2-DVsjb2QL.mjs', 'the host keeps importing the 2.42304.0 target name (R4)');
  // 2.42304.0 In / An / Rn / Ln / mt; ot is the path resolver's provider (2.42304.0 ft): X() = c(at) is the context the
  // file link reads toAbs from.
  for (const name of ['rr', 'Yn', 'ar', 'ir', 'lt', 'ot']) assert.ok(link.bindings.some(b => b.name === name), `c856385e2 ${name}`);
  assert.deepEqual(link.exports, { ot: 'PathResolverProvider', lt: 'usePathResolver' });
  // The session's file contexts are r3b-transcript's and files-changes' copies (linked, not sliced again).
  const linked = new Set(link.imports.filter(i => i.kind === 'linked').map(i => `${i.from}#${i.name}`));
  for (const key of ['../r3b-transcript/session-file-access.mjs#useSessionFileOpener', '../r3b-transcript/session-file-access.mjs#useDiffOpener',
    '../r3b-transcript/session-file-access.mjs#ReadRefusalContext', '../files-changes/file-gone-check.mjs#useFileGone',
    '../files-changes/session-context.mjs#CurrentSessionIdContext'])
    assert.ok(linked.has(key), key);
  const group = manifest.modules.find(m => m.target === 'group-status.mjs');
  const adapted = new Set(manifest.modules.flatMap(m => m.imports.filter(i => i.kind === 'adapter').map(i => i.name)));
  for (const name of ['HostToolResult', 'FileLink', 'useFileOpener', 'fileLanguage']) assert.ok(!adapted.has(name), name);
  for (const name of ['TranscriptMarkdown', 'useRequestStore', 'useOpenSettingsHref', 'FileMenuTrigger', 'FilePathMenuItems',
    'SessionRenameBody', 'InboxMessageBody', 'useCodeThemeLight', 'useCodeThemeDark'])
    assert.ok(adapted.has(name), name);
  assert.ok(group.bindings.some(b => b.name === 'ROe'));
  // datadog / RUM never enter the area (D17): shared-0 z (the RUM client, read directly in 3.6556.2), B (trackAction) and
  // bN (reportError) are pinned adapters.
  for (const name of ['datadogRum', 'reportError', 'trackAction']) assert.ok(adapted.has(name), name);
  assert.ok(!manifest.modules.some(m => /vendor-datadog|vendor-query|vendor-router/.test(m.source)));
});

test('Shiki\'s lazily loaded grammars, themes and wasm are byte-for-byte copies under their own names', () => {
  const verbatim = manifest.modules.filter(m => m.verbatim);
  assert.equal(verbatim.length, 249, '248 found through lazyVerbatim plus the rolldown runtime');
  for (const m of verbatim) {
    assert.equal(m.target, m.source);
    const bytes = fs.readFileSync(path.join(dir, m.target));
    assert.equal(sha(bytes), m.sha256, m.target);
    assert.ok(bytes.equals(fs.readFileSync(path.join(reference, m.source))), `${m.target} is the installed chunk`);
    for (const dep of m.imports) assert.ok(verbatim.some(v => `./${v.target}` === dep.from), `${m.target} -> ${dep.from}`);
  }
  // The importers keep their original specifiers: c5a058668 bundledLanguages, the inlined oniguruma wasm, the themes.
  const languages = fs.readFileSync(path.join(dir, 'rows-c5a058668-DBnBP7Qc.mjs'), 'utf8');
  assert.equal((languages.match(/import\("\.\/c[0-9a-f]{8}-[\w-]+\.js"\)/g) ?? []).length, 235);
  assert.match(fs.readFileSync(path.join(dir, 'rows-c68fd9df8-CJ4k-Myz.mjs'), 'utf8'), /import\("\.\/c7c157339-BCwwaLv8\.js"\)/);
  assert.ok(fs.readFileSync(path.join(dir, 'c7c157339-BCwwaLv8.js'), 'utf8').startsWith('var e=Uint8Array.from(atob("AGFzbQ'), 'the wasm is inline');
  // Nothing is served from /assets/v1: prepare-ui needs no copy for this area.
  assert.deepEqual(manifest.publicAssets, []);
  // The registrations the chunks run on load are carried: the diffs-container element, the Claude code themes.
  assert.match(fs.readFileSync(path.join(dir, 'rows-c64baa838-cddTLIc9.mjs'), 'utf8'), /customElements\.define\(/);
  assert.match(fs.readFileSync(path.join(dir, 'rows-c5d464fa3-Bot02AbX.mjs'), 'utf8'), /m\(y, \(\) => Promise\.resolve\(structuredClone\(E\)\)\)/);
  // property-information's Info prototypes moved to vendor-markdown in 3.6556.2 (carried there).
  assert.match(fs.readFileSync(path.join(dir, 'rows-vendor-markdown-CTRWgQFt.mjs'), 'utf8'), /\.prototype\.normal = \{\}/);
});

const read = { id: 'r1', turnId: 't', type: 'commandExecution', command: "sed -n '1,2p' src/a.js", status: 'completed',
  aggregatedOutput: 'const a = 1;\nconst b = 2;\n', commandActions: [{ type: 'read', path: '/w/src/a.js', name: 'a.js' }] };
const edit = { id: 'e1', turnId: 't', type: 'fileChange', status: 'completed', changes: [{ path: '/w/src/a.js', kind: { type: 'update' }, diff: '@@ -1,2 +1,2 @@\n const a = 1;\n-const b = 2;\n+const b = 3;\n' }] };
const cmd = { id: 'c1', turnId: 't', type: 'commandExecution', command: 'npm test', description: 'Run the tests', status: 'completed', aggregatedOutput: '\x1b[32mPASS\x1b[0m 3 tests', exitCode: 0 };

test('a Read row: the original file link in the row, the pierre File preview under it', () => {
  const html = strip(render(read));
  assert.match(html, /<span dir="auto">Read<\/span>[\s\S]*<span role="button" tabindex="0" data-file-ref="\/w\/src\/a\.js">a\.js<\/span>/,
    'An: the link as the desktop draws it with a Files opener, carrying the path for the host file menu');
  // 3.6556.2: the highlighted preview (pierre File) is the lazy entry epitaxy_code_highlight (c19e90103 Xc over shared-104
  // mm); before its chunk has loaded — always under SSR — the original draws the CDS skeleton in its place.
  assert.match(html, /data-cds="SkeletonGroup"/, 'Fd: the highlighted preview, loading (PooledFile)');
  assert.doesNotMatch(html, /<diffs-container>/);
  assert.doesNotMatch(html, /sft-read/);
  // Without a Files opener (no session) the name is plain text: In's fallback.
  const plain = strip(renderToStaticMarkup(h(Rows.TranscriptRowsScope, { sessionKey: 'code:s' }, h(Session.SourceMessage, { item: read, sessionKey: 's' }))));
  assert.match(plain, /<bdi>a\.js<\/bdi>/);
  assert.doesNotMatch(plain, /data-file-ref=/);
});

test('an Edit row: preferDiff file link, diff counts, the pierre FileDiff body', () => {
  const html = strip(render(edit));
  assert.match(html, /<span dir="auto">Edited<\/span>/);
  assert.match(html, /data-cds="DiffIndicator" data-size="xs" dir="ltr"[\s\S]*1 added, 1 removed/, 'TR-T14: the counts read left to right');
  // 3.6556.2: the diff body is a lazy entry too (epitaxy_inline_diff / epitaxy_code_highlight): its loading skeleton.
  assert.match(html, /data-cds="SkeletonGroup"/);
});

test('a command row: Cu with its Bash header, the command line and the ANSI output', () => {
  const html = strip(render(cmd));
  assert.match(html, /Ran the tests/);
  assert.match(html, /<span>Bash<\/span>/);
  assert.match(html, /<span aria-hidden="true" data-find-omitted="">\$\u00a0<\/span>/, 'ga: the prompt before the highlighted command');
  assert.match(html, /PASS/);
  assert.doesNotMatch(html, /\x1b/);
});

test('host services: the file menu trigger carries the path, the request store answers pending approvals', () => {
  const trigger = h('span', { role: 'button' }, 'a.js');
  const menu = h(Adapters.FilePathMenuItems, { path: '/w/a.js', line: 3 });
  const out = renderToStaticMarkup(h(Adapters.FileMenuTrigger, { trigger, beforeOpen: () => null }, menu));
  assert.equal(out, '<span role="button" data-file-ref="/w/a.js" data-file-line="3">a.js</span>');
  // shared-11 X through a selector (cb6930dae yo: a running Bash call waiting on an approval is not live).
  let seen;
  function Probe() { seen = Adapters.useRequestStore(state => state.requestsBySession.s?.c9?.status ?? 'none'); return null; }
  renderToStaticMarkup(h(Host.TranscriptHostScope.Provider, { value: { sessionId: 's', turnStartedAt: null, awaiting: true } },
    h(Tools.TranscriptToolScope.Provider, { value: { pendingApprovalItemIds: new Set(['c9']) } }, h(Probe))));
  assert.equal(seen, 'pending');
  renderToStaticMarkup(h(Probe));
  assert.equal(seen, 'none');
  assert.equal(Adapters.reportError(Error('x')), undefined);
  assert.equal(Adapters.trackAction('x', {}), undefined);
});
